{
  "application": "poster-generation",
  "case_id": "case-culture-books-production-history",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A1-portrait",
    "audience": "data-report",
    "tone": "data-forward, engaging",
    "venue": null
  },
  "brief": {
    "title": "The History of Books: From Manuscripts to Mass Production",
    "one_liner": "A data-driven look at how book production evolved from rare handwritten manuscripts to millions of printed titles over the past 1,500 years.",
    "goal": "The viewer should understand the dramatic transformation in book production triggered by the printing press, appreciate the long-term trends in manuscript and book output across centuries, and recognize books as a proxy for literacy, wealth, and cultural development."
  },
  "sections": [
    {
      "id": "manuscripts-era",
      "title": "The Manuscript Era (6th–15th Century)",
      "objective": "Show how manuscript production grew slowly over nearly a millennium before the printing press, highlighting the scarcity and luxury status of written works."
    },
    {
      "id": "printing-revolution",
      "title": "The Gutenberg Revolution (~1440)",
      "objective": "Illustrate the explosive impact of the printing press on book production, with data on printed books per half century from the 15th century onward."
    },
    {
      "id": "modern-publishing",
      "title": "Modern Book Publishing & Consumption",
      "objective": "Present per-capita metrics on new book titles published and annual book consumption, showing wide variation across countries."
    },
    {
      "id": "books-as-proxy",
      "title": "Books as a Mirror of Society",
      "objective": "Convey the idea that book production data reflects broader trends in literacy, income, education, religion, and cultural development."
    }
  ],
  "metrics": [
    {
      "label": "Gutenberg's Printing Press Invented",
      "value": "~1440"
    },
    {
      "label": "Centuries of Manuscript Data Covered",
      "value": "6th–15th century (10 centuries)"
    },
    {
      "label": "Printed Book Data Span",
      "value": "1500–2009 (per half century & per year)"
    },
    {
      "label": "Book Definition (UNESCO standard)",
      "value": "Published title with >49 pages"
    },
    {
      "label": "Key Data Source",
      "value": "Buringh & Van Zanden (2009); Fink-Jensen (2015)"
    }
  ]
}

